flex flex-wrap gap-2"><button class="btn btn-primary" type="submit" name="action" value="save_vocabulary"><i class="fa-solid fa-floppy-disk me-1" aria-hidden="true"></i>Stammdatenprüfung speichern</button><button class="btn btn-outline-info" type="submit" name="action" value="diagnose"><i class="fa-solid fa-stethoscope me-1" aria-hidden="true"></i>KI-Testanfrage</button></div></section></div>
