<script>
(() => {
  const panel = document.getElementById('settings-ai-panel');
  const select = panel?.querySelector('[data-ai-provider-preset]');
  if (!panel || !select || select.dataset.bound === '1') return;
  select.dataset.bound = '1';
  const presets = {
    innogpt: {name: 'innoGPT', base_url: 'https://app.innogpt.de/api/ext/v1', header_name: 'Authorization', pricing_url: 'https://docs.innogpt.de/en/help/articles/8468742-usage-limits-andamp-fair-use-policy', vocabulary_ai_model: 'smart'},
    ionos: {name: 'IONOS AI Model Hub', base_url: 'https://openai.inference.de-txl.ionos.com/v1', header_name: 'Authorization', pricing_url: 'https://docs.ionos.com/cloud/ai/ai-model-hub/ai-model-hub'},
    ovh: {name: 'OVHcloud AI Endpoints', base_url: 'https://oai.endpoints.kepler.ai.cloud.ovh.net/v1', header_name: 'Authorization', pricing_url: 'https://help.ovhcloud.com/csm/en-au-public-cloud-ai-endpoints-code-assistant?id=kb_article_view&sysparm_article=KB0067282', vocabulary_ai_model: 'mistral@latest'}
  };
  select.addEventListener('change', () => {
    const preset = presets[select.value];
    if (!preset) return;
    Object.entries(preset).forEach(([name, value]) => {
      const field = panel.querySelector(`[name="${name}"]`);
      if (!field) return;
      if (field.tagName === 'SELECT' && ![...field.options].some(option => option.value === value)) field.add(new Option(value === 'smart' ? 'smart · automatische Modellauswahl' : (value === 'mistral@latest' ? 'mistral@latest · automatisch aktuelles Mistral-Modell' : value), value));
      field.value = value;
    });
    panel.querySelector('[name="api_token"]')?.focus();
  });
})();
</script>
